<script lang="ts">
	// @ts-nocheck
	import { onMount } from 'svelte'
	import { asset } from '$hangarkit'
	import data from '$data'
	import { navigate } from '../lib/navigation'
	import TaskStatusBadge from '../components/TaskStatusBadge.svelte'
	import ViewModeSwitcher from '../components/ViewModeSwitcher.svelte'
	import { smart_api } from '../lib/smart-api'
	let { task_id = '' } = $props()
	let task = $state(null), loading = $state(true), refreshing = $state(false), error = $state('')
	let output_fields = $state([]), expanded = $state({ input: false, progress: true, output: false }), view_mode = $state({ input: 'parsed', progress: 'parsed', output: 'parsed' }), status_loaded = $state(''), interrupt_command = $state('{}'), continuing = $state(false), copied = $state(''), selected_node = $state('')
	data.smart_workflow_output_fields.subscribe((items) => output_fields = [...items].sort((a, b) => (a.order || 0) - (b.order || 0)))
	const terminal = () => ['success', 'failed', 'interrupted'].includes(task?.status || '')
	function node_rows() { return task?.parsed_progress?.nodes || Object.entries(task?.debug_tree?.node_id_to_summary || {}).map(([id, node]) => ({ id, name: `Node ${id}`, type: 'workflow node', status: node?.status || 'unknown', errors: node?.error_messages || [], latency: node?.time_info?.latency })) }
	function has_edge(from, to) { return (task?.parsed_progress?.traversed_edges || []).some((edge) => edge.from === from && edge.to === to) }
	function selected() { return node_rows().find((node) => node.id === selected_node) || node_rows()[0] }
	function set_status_panels() { if (!task || status_loaded === task.status) return; status_loaded = task.status; expanded = { input: false, progress: !terminal() || task.status === 'interrupted', output: ['success', 'failed'].includes(task.status) }; selected_node = node_rows()[0]?.id || '' }
	async function load(refresh = false) { if (!task_id) return; refreshing = refresh; error = ''; try { const result = refresh ? await smart_api.refresh_task(task_id) : await smart_api.get_task(task_id); task = result.task; set_status_panels() } catch (err) { error = err instanceof Error ? err.message : String(err) } finally { loading = false; refreshing = false } }
	onMount(() => { void load(); const interval = window.setInterval(() => { if (task && !terminal()) void load(true) }, 3500); return () => window.clearInterval(interval) })
	const datetime = (value) => value ? new Date(value).toLocaleString() : '—'
	const progress = () => Math.min(100, Math.max(0, Number(task?.progress_percent || (terminal() ? 100 : 0))))
	const entries = (value) => value && typeof value === 'object' && !Array.isArray(value) ? Object.entries(value) : []
	function display(value) { return value === undefined || value === null ? '—' : typeof value === 'string' ? value : JSON.stringify(value) }
	function is_url(value) { try { const url = new URL(String(value)); return ['http:', 'https:'].includes(url.protocol) } catch { return false } }
	function cost_value() { return task?.provider_cost === undefined || task?.provider_cost === null ? '—' : String(task.provider_cost) }
	function toggle(panel) { expanded = { ...expanded, [panel]: !expanded[panel] } }
	async function copy_json(value, label) { try { await navigator.clipboard.writeText(JSON.stringify(value || {}, null, 2)); copied = label; window.setTimeout(() => copied = '', 1600) } catch { error = 'Copy is unavailable in this browser. Select the JSON manually.' } }
	async function continue_task() { try { continuing = true; error = ''; const command = JSON.parse(interrupt_command || '{}'); const result = await smart_api.continue_interrupt(task.id, { interrupt_type: task.interrupt?.interrupt_type || 'human_in_loop', interrupt_command: command }); task = result.task; set_status_panels() } catch (err) { error = err instanceof Error ? err.message : 'Interrupt command must be valid JSON.' } finally { continuing = false } }
</script>

<section class="page">
	<button class="back" onclick={() => navigate('/')}>← All tasks</button>
	{#if loading}<div class="card loading">Loading task…</div>{:else if task}
		<header class="heading"><div><div class="title-line"><TaskStatusBadge status={task.status} /><p>SMART workflow run</p></div><h2>{task.title || task.smart_thread_id || 'Workflow task'}</h2><small>Created by {task.submitted_by || 'Hangar user'} · Thread {task.smart_thread_id || 'is being created'}</small></div></header>
		{#if error}<p class="error">{error}</p>{/if}
		<section class="overview card"><div class="time-flow"><span>Started</span><strong>{datetime(task.started_at || task.created)}</strong><i></i><span>Duration</span><strong>{task.duration_ms ? `${Math.round(task.duration_ms / 1000)} seconds` : '—'}</strong><i></i><span>Ended</span><strong>{datetime(task.completed_at)}</strong></div><div class="cost"><span>Cost</span><strong>{cost_value()}</strong></div><button onclick={() => load(true)} disabled={refreshing || terminal()}>{refreshing ? 'Refreshing…' : terminal() ? 'Final state' : 'Refresh progress'}</button></section>
		<section class="panels">
			<article class:open={expanded.input} class="panel card"><button class="panel-head" onclick={() => toggle('input')}><span><i>01</i><strong>Submitted input</strong><small>{entries(task.input_summary || task.input_variables).length} values captured with this run</small></span><b>{expanded.input ? '−' : '+'}</b></button>{#if expanded.input}<div class="panel-body"><div class="mode"><ViewModeSwitcher value={view_mode.input} on_select={(value) => view_mode = { ...view_mode, input: value }} /></div>{#if view_mode.input === 'parsed'}<dl class="kv">{#each entries(task.input_summary || task.input_variables) as [key, value] (key)}<div><dt>{key}</dt><dd>{display(value)}</dd></div>{/each}</dl>{:else}<div class="json-box"><button onclick={() => copy_json(task.input_summary || task.input_variables, 'input')}>{copied === 'input' ? 'Copied' : 'Copy JSON'}</button><pre>{JSON.stringify(task.input_summary || task.input_variables || {}, null, 2)}</pre></div>{/if}</div>{/if}</article>
			<article class:open={expanded.progress} class="panel card"><button class="panel-head" onclick={() => toggle('progress')}><span><i>02</i><strong>Workflow progress</strong><small>{task.progress_summary?.completed_nodes || 0} of {task.progress_summary?.total_nodes || 0} nodes · {progress()}%</small></span><b>{expanded.progress ? '−' : '+'}</b></button>{#if expanded.progress}<div class="panel-body"><div class="progress-label"><span>Execution progress</span><strong>{progress()}%</strong></div><div class="progress-line"><i style={`width:${progress()}%`}></i></div><div class="mode"><ViewModeSwitcher value={view_mode.progress} parsed_label="Timeline" on_select={(value) => view_mode = { ...view_mode, progress: value }} /></div>{#if view_mode.progress === 'parsed'}<div class="node-layout"><div class="nodes">{#each node_rows() as node, index (node.id)}<button class:selected={selected_node === node.id} onclick={() => selected_node = node.id}><span class:success={node.status === 'success'} class:failed={node.status === 'failed'} class:running={['running','processing'].includes(node.status)}>{node.status}</span><div><strong>{node.name}</strong><small>{node.type}{node.is_parallel ? ' · parallel' : ''}</small></div><em>{node.latency ? `${Number(node.latency).toFixed(2)}s` : '—'}</em></button>{#if index < node_rows().length - 1}<div class="node-connector" class:linked={has_edge(node.id, node_rows()[index + 1].id)}><i>↓</i>{#if has_edge(node.id, node_rows()[index + 1].id)}<span>traversed</span>{/if}</div>{/if}{/each}{#if !node_rows().length}<p class="muted">Waiting for SMART node details.</p>{/if}</div>{#if selected()}<aside class="node-inspector"><div><small>Selected node</small><h3>{selected().name}</h3><p>{selected().type} · {selected().status}</p></div>{#if selected().errors?.length}<div class="node-error"><strong>What needs attention</strong>{#each selected().errors as message}<p>{message}</p>{/each}</div>{:else}<p class="muted">No node error details were reported.</p>{/if}<details class="node-io"><summary>Node inputs & outputs</summary><div><strong>Inputs</strong><dl class="mini-kv">{#each entries(selected().inputs) as [key, value]}<div><dt>{key}</dt><dd>{display(value)}</dd></div>{:else}<p class="muted">No inputs reported.</p>{/each}</dl></div><div><strong>Outputs</strong><dl class="mini-kv">{#each entries(selected().outputs) as [key, value]}<div><dt>{key}</dt><dd>{display(value)}</dd></div>{:else}<p class="muted">No outputs reported.</p>{/each}</dl></div></details></aside>{/if}</div><details class="metadata"><summary>Workflow metadata <span>system variables, output variables, and output settings</span></summary><div class="metadata-grid">{#each [['System variables', task.parsed_progress?.system_variables], ['Output variables', task.parsed_progress?.output_variables], ['Structured output setting', task.parsed_progress?.structured_output_setting]] as [label, value]}<div><strong>{label}</strong><div class="json-box compact"><button onclick={() => copy_json(value, label)}>{copied === label ? 'Copied' : 'Copy'}</button><pre>{JSON.stringify(value || {}, null, 2)}</pre></div></div>{/each}</div></details>{:else}<div class="json-box"><button onclick={() => copy_json(task.debug_tree, 'progress')}>{copied === 'progress' ? 'Copied' : 'Copy JSON'}</button><pre>{JSON.stringify(task.debug_tree || {}, null, 2)}</pre></div>{/if}</div>{/if}</article>
			<article class:open={expanded.output} class="panel card"><button class="panel-head" onclick={() => toggle('output')}><span><i>03</i><strong>{task.status === 'failed' ? 'Workflow result & error' : 'Workflow output'}</strong><small>{terminal() ? 'SMART returned a terminal response' : 'Available when the run completes'}</small></span><b>{expanded.output ? '−' : '+'}</b></button>{#if expanded.output}<div class="panel-body"><div class="mode"><ViewModeSwitcher value={view_mode.output} on_select={(value) => view_mode = { ...view_mode, output: value }} /></div>{#if view_mode.output === 'parsed'}{#if task.status === 'failed' && task.business_error}<div class="business-error"><strong>{task.business_error.code}</strong><p>{task.business_error.message}</p></div>{/if}<dl class="kv">{#each entries(task.status === 'failed' ? { errors: task.error_messages } : task.output) as [key, value] (key)}<div><dt>{key}</dt><dd>{#if is_url(value)}<a href={value} target="_blank" rel="noreferrer">{value}</a>{:else}{display(value)}{/if}</dd></div>{/each}{#if !entries(task.output).length && task.status !== 'failed'}<p class="muted">Waiting for SMART output.</p>{/if}</dl>{:else}<div class="json-box"><button onclick={() => copy_json(task.status === 'failed' ? { errors: task.error_messages, business_error: task.business_error } : task.output, 'output')}>{copied === 'output' ? 'Copied' : 'Copy JSON'}</button><pre>{JSON.stringify(task.status === 'failed' ? { errors: task.error_messages, business_error: task.business_error } : task.output || {}, null, 2)}</pre></div>{/if}</div>{/if}</article>
		</section>
		{#if task.status === 'interrupted'}<section class="card interrupt"><div><span>Action required</span><h3>Workflow needs your input</h3><p>{task.interrupt?.message || 'Provide the SMART interrupt command as JSON.'}</p></div><textarea bind:value={interrupt_command} aria-label="Interrupt command JSON"></textarea><button onclick={() => continue_task()} disabled={continuing}>{continuing ? 'Continuing…' : 'Continue workflow'}</button></section>{/if}
		{#if task.file_assets?.length}<section class="card assets-card"><div><span>Persisted assets</span><h3>Uploaded files</h3></div><ul class="assets">{#each task.file_assets as file (file.record_id || file.asset_filename)}<li><div><strong>{file.original_name || file.asset_filename}</strong><small>{file.field_name} · {file.size_bytes || 0} bytes</small></div><span><a href={asset(file.asset_filename)} target="_blank" rel="noreferrer">View</a><a href={asset(file.asset_filename, { download: true })}>Download</a></span></li>{/each}</ul></section>{/if}
	{:else}<div class="card loading">Task not found.</div>{/if}
</section>

<style>
.page{width:min(1080px,100%);margin:0 auto;display:grid;gap:1rem}.back{width:fit-content;padding:0;border:0;color:var(--accent-color,#3159db);background:transparent;font:inherit;cursor:pointer}.heading{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}.heading p,.heading h2,.heading small{margin:0}.heading p,.heading small,small,.muted{color:var(--muted-ink-color,#637083)}.heading p,.assets-card>div>span,.interrupt span{font-size:.72rem;letter-spacing:.05em;text-transform:uppercase}.heading h2{margin:.2rem 0;font-size:1.55rem;font-weight:550;letter-spacing:-.04em}.card{border:1px solid var(--border-color,#dbe2ec);border-radius:14px;background:var(--panel-background,#fff)}.loading{padding:1.1rem;color:var(--muted-ink-color,#637083)}.overview{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1rem;padding:1rem 1.1rem;align-items:end}.overview div{display:grid;gap:.3rem}.overview span{color:var(--muted-ink-color,#637083);font-size:.72rem;letter-spacing:.05em;text-transform:uppercase}.overview strong{font-size:.87rem;font-weight:550}.overview button{justify-self:end}.overview button:disabled{color:#667085;background:#eef1f5;opacity:1}.panels{display:grid;gap:.75rem}.panel{overflow:hidden}.panel.open{border-color:#cddaf8;box-shadow:0 8px 28px rgba(49,89,219,.07)}.panel-head{width:100%;display:flex;justify-content:space-between;align-items:center;padding:1rem 1.15rem;border:0;color:var(--ink-color,#172033);background:transparent;text-align:left;font:inherit;cursor:pointer}.panel-head>span{display:grid;grid-template-columns:32px auto;column-gap:.7rem;align-items:center}.panel-head i{grid-row:span 2;display:grid;width:32px;height:32px;place-items:center;border-radius:10px;color:var(--accent-color,#3159db);background:#edf2ff;font-size:.68rem;font-style:normal;font-weight:650}.panel-head strong{font-size:.94rem;font-weight:600}.panel-head small{grid-column:2;margin-top:.12rem;font-size:.76rem}.panel-head>b{color:var(--accent-color,#3159db);font-size:1.25rem;font-weight:400}.panel-body{padding:0 1.15rem 1.15rem}.mode{display:flex;gap:.35rem;margin:1rem 0 .85rem}.mode button,.json-box button{padding:.34rem .58rem;border:1px solid #dbe3f0;border-radius:7px;color:#637083;background:#fff;font:inherit;font-size:.75rem;cursor:pointer}.mode button.active{border-color:#c7d7ff;color:#3159db;background:#f0f4ff}.kv{margin:0;display:grid;gap:.5rem}.kv div{display:grid;grid-template-columns:minmax(145px,30%) 1fr;gap:.75rem;padding:.68rem .75rem;border-radius:9px;background:#f7f9fc}.kv dt{color:#64748b;font-size:.78rem}.kv dd{margin:0;overflow-wrap:anywhere;font:.8rem/1.5 ui-monospace,SFMono-Regular,monospace}.kv a{color:#3159db;text-decoration:underline;text-underline-offset:2px}.progress-label{display:flex;justify-content:space-between;margin-top:.95rem;color:#64748b;font-size:.78rem}.progress-label strong{color:var(--ink-color,#172033)}.progress-line{height:7px;margin-top:.4rem;overflow:hidden;border-radius:999px;background:#e8edf4}.progress-line i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#4d6de6,#8ba6ff)}.node-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(230px,.8fr);gap:.9rem}.nodes{display:grid;gap:.4rem}.nodes>button{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:.65rem;align-items:center;padding:.65rem .7rem;border:1px solid transparent;border-radius:9px;color:var(--ink-color,#172033);background:#f8fafe;text-align:left;font:inherit;cursor:pointer}.nodes>button.selected{border-color:#cbd9fb;background:#f1f5ff}.nodes span{width:fit-content;padding:.18rem .4rem;border-radius:99px;color:#637083;background:#e8edf4;font-size:.68rem}.nodes span.success{color:#15734e;background:#e5f7ef}.nodes span.failed{color:#b83441;background:#fff0f1}.nodes span.running{color:#a86310;background:#fff3df}.nodes strong,.nodes small{display:block}.nodes strong{font-size:.8rem;font-weight:600}.nodes small{margin-top:.12rem;font-size:.72rem}.nodes em{color:#637083;font-size:.72rem;font-style:normal}.node-inspector{display:grid;align-content:start;gap:.85rem;padding:.85rem;border:1px solid #dce5f5;border-radius:10px;background:#fbfcff}.node-inspector h3,.node-inspector p{margin:.2rem 0 0}.node-inspector h3{font-size:.9rem;font-weight:600}.node-inspector p{color:#637083;font-size:.76rem}.node-error{padding:.7rem;border-radius:8px;color:#8f3040;background:#fff3f4}.node-error strong{font-size:.76rem}.node-error p{color:inherit}.metadata{margin-top:.85rem;border-top:1px solid #e4eaf3;padding-top:.75rem}.metadata summary{color:#40506a;font-size:.8rem;cursor:pointer}.metadata summary span{color:#778399}.metadata-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.65rem;margin-top:.75rem}.metadata-grid>div{min-width:0}.metadata-grid>div>strong{color:#64748b;font-size:.75rem}.json-box{position:relative}.json-box>button{position:absolute;top:.55rem;right:.55rem;z-index:1;box-shadow:0 1px 4px #17203318}.json-box pre{max-height:360px;margin:0;overflow:auto;padding:.9rem;padding-top:2.8rem;border-radius:9px;background:#f5f7fb;color:#344054;font:.76rem/1.5 ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap;word-break:break-word}.json-box.compact{margin-top:.4rem}.json-box.compact pre{max-height:180px}.business-error{margin-bottom:.7rem;padding:.75rem .8rem;border-radius:9px;color:#973746;background:#fff1f3}.business-error strong{font-size:.76rem}.business-error p{margin:.25rem 0 0;font-size:.82rem}.interrupt{display:grid;grid-template-columns:1fr minmax(260px,.9fr) auto;gap:1rem;align-items:center;padding:1rem 1.1rem;border-color:#e3d2fa;background:linear-gradient(100deg,#fdfbff,#f8f4ff)}.interrupt h3,.interrupt p{margin:.25rem 0 0}.interrupt h3{font-size:.95rem;font-weight:600}.interrupt p{color:#677086;font-size:.8rem}.interrupt textarea{min-height:80px;box-sizing:border-box;width:100%;padding:.65rem;border:1px solid #d8c7ef;border-radius:8px;background:#fff;font:.77rem/1.4 ui-monospace,monospace;resize:vertical}.assets-card{padding:1rem 1.1rem}.assets-card h3{margin:.25rem 0 .8rem;font-size:.95rem;font-weight:600}.assets{display:grid;gap:.5rem;margin:0;padding:0;list-style:none}.assets li{display:flex;justify-content:space-between;gap:1rem;align-items:center;padding:.65rem .75rem;border:1px solid #e0e7f0;border-radius:9px;background:#fafcff}.assets strong,.assets small{display:block}.assets small{margin-top:.15rem}.assets li>span{display:flex;gap:.4rem}.assets a{padding:.35rem .55rem;border:1px solid #d6e0f0;border-radius:6px;color:var(--accent-color,#3159db);background:#fff;font-size:.76rem;text-decoration:none}.error{margin:0;padding:.75rem;border-radius:9px;color:var(--danger-color,#cc3b45);background:#fff0f1}button:not(.panel-head):not(.back){border:0;border-radius:7px;padding:.6rem .8rem;color:#fff;background:var(--accent-color,#3159db);font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.65;cursor:default}@media(max-width:820px){.overview{grid-template-columns:repeat(2,1fr)}.overview button{grid-column:1/-1;justify-self:stretch}.node-layout,.interrupt{grid-template-columns:1fr}.metadata-grid{grid-template-columns:1fr}.interrupt button{justify-self:start}}@media(max-width:580px){.heading{align-items:flex-start;flex-direction:column}.kv div{grid-template-columns:1fr}.assets li{align-items:stretch;flex-direction:column}.assets li>span a{flex:1;text-align:center}}
.title-line{display:flex;align-items:center;gap:.55rem}.title-line p{color:var(--muted-ink-color,#637083);font-size:.72rem;letter-spacing:.05em;text-transform:uppercase}.overview{grid-template-columns:minmax(0,1fr) 100px auto}.time-flow{display:flex!important;align-items:center;gap:.55rem}.time-flow span{font-size:.67rem!important}.time-flow strong{white-space:nowrap}.time-flow i{height:22px;border-left:1px solid #dbe3ec}.overview .cost{display:grid;gap:.25rem}.node-io{display:grid;gap:.6rem;padding-top:.15rem}.node-io summary{color:#40516b;font-size:.78rem;cursor:pointer}.node-io>div{display:grid;gap:.35rem}.node-io>div>strong{font-size:.72rem;color:#64748b}.mini-kv{display:grid;gap:.25rem;margin:0}.mini-kv div{display:grid;grid-template-columns:90px 1fr;gap:.4rem;padding:.35rem .4rem;border-radius:6px;background:#f4f7fb}.mini-kv dt,.mini-kv dd{margin:0;overflow-wrap:anywhere;font:.7rem/1.35 ui-monospace,SFMono-Regular,monospace}.mini-kv dt{color:#64748b}

/* Keep the timeline intrinsic when the inspector expands. */
.node-layout{align-items:start}.nodes{align-content:start}

/* The execution list is a neutral timeline, not a set of primary buttons. */
.mode button:not(.panel-head):not(.back),.json-box button:not(.panel-head):not(.back){border:1px solid #dbe3f0!important;color:#5d6c82!important;background:#fff!important;font-weight:550!important;box-shadow:none!important}.mode button.active:not(.panel-head):not(.back){border-color:#c7d7ff!important;color:#3159db!important;background:#f0f4ff!important}.nodes{position:relative;gap:.45rem;padding-left:.1rem}.nodes::before{content:none}.nodes>button:not(.panel-head):not(.back){position:relative;grid-template-columns:84px minmax(0,1fr) auto;min-height:66px;padding:.7rem .8rem;border:1px solid #e2e8f0!important;border-radius:10px!important;color:#253246!important;background:#fff!important;box-shadow:0 1px 2px rgba(25,40,70,.025)!important;font-weight:400!important}.nodes>button:not(.panel-head):not(.back):hover{border-color:#c6d4eb!important;background:#fbfcff!important}.nodes>button.selected:not(.panel-head):not(.back){border-color:#b9cdfb!important;background:#f5f8ff!important;box-shadow:0 0 0 3px rgba(64,104,220,.08)!important}.nodes span{position:relative;z-index:1;justify-self:start;min-width:58px;padding:.22rem .42rem;text-align:center;font-size:.67rem;font-weight:650}.nodes strong{color:#253246;font-size:.84rem;font-weight:600}.nodes small{color:#748299;font-size:.72rem}.nodes em{padding-left:.6rem;color:#7b8798;font-size:.72rem}.node-connector{display:flex;align-items:center;gap:.38rem;height:22px;padding-left:25px;color:#a0acbd;font-size:.66rem}.node-connector i{display:grid;width:17px;height:17px;place-items:center;border:1px solid #dce4ef;border-radius:50%;color:#93a2b8;background:#fff;font-size:.72rem;font-style:normal}.node-connector.linked i{border-color:#c4d2fa;color:#5270e8;background:#f0f4ff}.node-connector.linked span{color:#7187c9}.node-inspector{border-color:#dce5f1;background:#fbfcfe;box-shadow:0 1px 3px rgba(25,40,70,.03)}.node-inspector>div:first-child{padding-bottom:.55rem;border-bottom:1px solid #e9eef5}.node-inspector h3{color:#253246;font-size:.95rem}.node-io{max-height:420px;overflow:auto;padding-right:.2rem}.kv{max-height:360px;overflow:auto;padding-right:.25rem}.progress-line{height:8px;background:#edf1f6}.progress-line i{background:linear-gradient(90deg,#5270e8,#8ba6ff);box-shadow:0 1px 3px rgba(49,89,219,.28)}@media(max-width:820px){.overview{grid-template-columns:1fr}.time-flow{align-items:flex-start;flex-direction:column}.time-flow i{width:18px;height:0;border-top:1px solid #dbe3ec;border-left:0}.overview .cost{grid-column:auto}.nodes>button:not(.panel-head):not(.back){grid-template-columns:76px minmax(0,1fr) auto}}
</style>
